  ('11089', '11089', 'Annette Brave', 'AB', 'F', 61, '05/18/1965', 'yue', 'SCAN Health Plan', ARRAY['CCM', 'DM', 'SNP', 'AWV', 'WLCP', 'CMP', 'TOC IP', 'HICM']::text[], ARRAY['Type 2 diabetes', 'Hypertension', 'COPD', 'Hyperlipidemia']::text[], 41, 47, '["ED visit 11/10 for chest pain; ACS ruled out","A1c 7.4% on 09/24, above the < 7% target","Home BP 146/90 on 11/01"]'::jsonb, 'Annette was seen in the ED on 11/10 for chest pain; ACS was ruled out, and the agent has her on a live call now. Her A1c was 7.4% on 09/24 against a target under 7%, home blood pressure read 146/90 on 11/01, and her CCM care plan review has been due since 10/24.', '2026-11-11T08:00:00Z', '09/24/2026', 30, 'CCM', 8, 20, '11/11/2026', 'Agent call', 'Erica', 'Fold Demo'),
